WITH scored AS (SELECT *, AVG(amount) OVER w_grp AS amount_avg_2_prior, AVG(amount) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share, ROW_NUMBER() OVER w_recent AS seq_no FROM payments WINDOW w_grp AS (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), w_recent AS (ORDER BY amount DESC, id)) SELECT s.id, s.order_id, s.method, s.amount, s.paid_at, s.status, s.amount_avg_2_prior, s.amount_avg_5_prior, s.amount_share, CASE WHEN status RLIKE '^(FAILED|SUCCESS)$' THEN 'CORE' ELSE 'GROUP_B' END AS status_zone, (SELECT MAX(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS max_payment_amount FROM scored s;
